/* 영업일 관리 (8030) */ /* AdminBusinessDayMapper.selectBusinessDayList */ MERGE INTO CSPD118TM A USING DUAL ON (A.BAS_DT = #{basDt})
WHEN MATCHED THEN UPDATE SET A.HLDY_DSCD = #{hldyDscd}, A.HLDY_TXT = #{hldyTxt}, A.TRN_LOG_SRNO = #{trnLogSrno}
WHEN NOT MATCHED THEN INSERT (A.BAS_DT, A.WKD_CD, A.HLDY_DSCD, A.TRN_LOG_SRNO, A.LST_DB_CHG_ID, A.LST_DB_CHG_DTM, A.HLDY_TXT) VALUES (#{basDt}, #{wkdCd}, #{hldyDscd}, #{trnLogSrno}, #{lstDbChgId}, TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF6'), #{hldyTxt} )
